def fingerprint(record):return {k:record.get(k) for k in ['id','heading','path','canonical_body_key','body_sha256']}
def reconcile(records,cfg):
 if hash_json(cfg)!=CONFIG_SHA:return records
 for url,q in INTERNAL.items():
  owner=records.get(q['owner_id']);target=records.get(q['target']['id']);witness=records.get(q['substantive_target_witness']['id'])
  if not owner or not target or not witness:continue
  if owner.get('body_sha256')!=q['owner_body_sha256'] or owner.get('heading')!=q['owner_heading']:continue
  if fingerprint(target)!=q['target'] or fingerprint(witness)!=q['substantive_target_witness']:continue
  if target.get('source_url')!=q['target_source_url']:continue
  if not witness.get('text','').replace('[IMAGE]','').strip() or digest(witness['text'].encode())!=q['substantive_target_witness_text_sha256']:continue
  if not any(a.get('attributes',{}).get('href')==q['literal_href'] for a in owner.get('links',[])):continue
  if not any(a['url']==url for a in owner['assets']):continue
  owner['assets']=[a for a in owner['assets'] if a['url']!=url]
  owner.setdefault('qualified_reference_dispositions',[]).append({'type':'qualified_malformed_internal_source_cross_reference','original_malformed_url':url,'required_external_document':False,'target_source_binding':copy.deepcopy(q),'reason':'Literal sourcefragment identifies the unique acquired samepublication node/path/heading with retained substantive targetbody. Originalmalformedhref/link/text remain unchanged; no repairedURL requested/invented.'})
 q=ALTERNATIVE;owner=records.get(q['owner_id'])
 if owner and owner.get('body_sha256')==q['owner_body_sha256'] and owner.get('heading')==q['owner_heading'] and any(a.get('attributes',{}).get('href')==q['original_literal_href'] for a in owner.get('links',[])):
  for a in owner['assets']:
   if a['url']!=q['original_url']:continue
   a['original_source_url']=q['original_url'];a['url']=q['url'];a['source_qualified_alternative']=copy.deepcopy(q)
   owner.setdefault('qualified_reference_dispositions',[]).append({'type':'qualified_same_city_ordinance_edition_document_alternative','original_failed_url':q['original_url'],'qualified_source_url':q['url'],'source_binding':copy.deepcopy(q),'required_document':True,'reason':'ExactOverlandPark/POC-3529/42ndEdition/2026/LKM identity; observedcurrentpublisherlink and fullnativeSHA/pages/coverpins. Original404retained; no newer/differentedition or accessstop bypass.'})
 return qualify_source_empty(records,cfg)

def qualify_bound_document(records,url,data):
 bindings=[a['source_qualified_alternative'] for r in records.values() for a in r['assets'] if a['url']==url and a.get('source_qualified_alternative')]
 if not bindings:return None
 for q in bindings:
  if q!=ALTERNATIVE:raise ValueError('Unqualified alternative source binding')
  if digest(data)!=q['expected_sha256']:raise ValueError('Qualified alternative native SHA/edition mismatch')
  from pypdf import PdfReader
  reader=PdfReader(io.BytesIO(data),strict=True)
  if len(reader.pages)!=q['expected_pages']:raise ValueError('Qualified alternative physicalpagecount mismatch')
  for p in q['cover_pages']:
   text=''.join(c.casefold() for c in (reader.pages[p['physical_page']-1].extract_text() or '') if c.isalnum())
   if digest(text.encode())!=p['normalized_text_sha256']:raise ValueError('Qualified alternative city/ordinance/edition/publisher witness mismatch')
 return copy.deepcopy(ALTERNATIVE)
